// End-to-end test: build an index from synthetic genomes, query synthetic reads
// against it in-process, and check the result against known ground truth.
//
// This is the first test to include both UniqSketchUtil.hpp and
// QuerySketchUtil.hpp -- possible only since the config refactor removed the
// file-scope globals that made the two headers mutually exclusive.
//
// The fixtures in test/e2e/ are generated by make_fixtures.py from a fixed seed
// (see that file for the design). In brief: two unrelated 20 kb genomes (refA,
// refB), a near-identical variant of the first (refA_var, 12 substitutions), and
// a fourth genome (refC) that is sequenced but deliberately not indexed. Reads
// are error-free and mixed 7000 / 2500 / 500 / 500.
//
// What each check protects against:
//
//   abundance      the paper's formula (count_i / sum count_j over reported
//                  references) and its proportionality to depth. Previously had
//                  no automated protection at all.
//   refA_var       the close-strain regime. Its only unique k-mers are those
//                  overlapping the 12 edits, so its signatures are packed into a
//                  few short regions (visible as count >> reads in the result,
//                  the same packing effect seen on real near-identical strains).
//                  Any error in how shared k-mers are excluded from a sibling's
//                  unique set shows up here as leaked abundance.
//   refC absent    an organism present in the sample but not in the index must
//                  produce no row -- not a zero row, no row (README: "absent
//                  means not called").
//   determinism    two index builds in one process must be byte-identical. This
//                  caught a real gap when first written: buildSketch wrote each
//                  reference's block from inside a parallel loop, so line order
//                  followed thread completion.
//
// What this test does NOT catch, deliberately: data races. The Bloom-filter race
// fixed in v1.6.1 needs two threads to insert the same k-mer within nanoseconds
// of each other; on 20 kb fixtures streamed in microseconds that window almost
// never opens, and it was verified that this test passes against the racy
// implementation. Races are the job of the dedicated concurrency test in
// bloomfiltertest, which forces the collision with a spin barrier and fails
// deterministically against the old code. An end-to-end test checks the
// arithmetic and the contracts; it is not a substitute for that.
//   reads column   every reported reference must have reads <= count (a read
//                  contributes at least one hit) and reads > readCutoff.
#include <cassert>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

#include <sys/stat.h>

#include "ntcard.hpp"
#include "FileUtil.hpp"
#include "UniqSketchUtil.hpp"
#include "QuerySketchUtil.hpp"

namespace {

const std::string FIX = "e2e/";
const std::string WORK = "e2e_work/";

struct Row {
    double abundance;
    unsigned count;
    size_t reads;
    size_t sigsHit;
    size_t sigsTotal;
    std::string resolution;
};

std::map<std::string, Row> readResult(const std::string& path) {
    std::map<std::string, Row> rows;
    std::ifstream in(path);
    std::string line;
    std::getline(in, line);   // header
    while (std::getline(in, line)) {
        std::istringstream ss(line);
        std::string ref;
        Row r;
        ss >> ref >> r.abundance >> r.count >> r.reads >> r.sigsHit >> r.sigsTotal >> r.resolution;
        assert(!ss.fail() && "result row has fewer columns than the documented schema");
        rows[ref] = r;
    }
    return rows;
}

std::map<std::string, double> readTruth() {
    std::map<std::string, double> t;
    std::ifstream in(FIX + "truth.tsv");
    std::string line;
    std::getline(in, line);
    while (std::getline(in, line)) {
        std::istringstream ss(line);
        std::string ref;
        unsigned reads;
        double ab;
        ss >> ref >> reads >> ab;
        t[ref] = ab;
    }
    return t;
}

std::string fileContents(const std::string& path) {
    std::ifstream in(path, std::ios::binary);
    std::stringstream ss;
    ss << in.rdbuf();
    return ss.str();
}

// Run the index build exactly as uniqsketch's main does for a flat index.
void buildIndex(const std::string& outdir, const std::string& sketchOut) {
    mkdir(outdir.c_str(), 0777);

    UniqSketchConfig cfg;
    cfg.kmerLen = 31;
    cfg.sketchnum = 100;
    cfg.outdir = outdir;
    cfg.outfile = sketchOut;
    cfg.refstat = outdir + "/db_uniq_count.tsv";
    cfg.threads = 4;

    std::vector<std::string> refs = {FIX + "refA.fa", FIX + "refB.fa", FIX + "refA_var.fa"};
    cfg.numRef = refs.size();

    size_t totalKmers = 0;
    getCardinality(totalKmers, cfg.dbfSize, cfg.sbfSize, cfg.kmerLen, cfg.threads, refs);
    bool sized = resolveBloomSizes(totalKmers, cfg.dbfSize, cfg.sbfSize);
    assert(sized && "fixture genomes must yield enough k-mers to size the filters");

    BloomFilter dbFilter(cfg.m1(), cfg.nhash1, cfg.kmerLen);
    identifyUniqKmers(cfg, refs, dbFilter);
    buildSketch(cfg, cfg.refstat, dbFilter);
}

// Run the query exactly as querysketch's main does for a flat index.
void runQuery(const std::string& sketch, const std::string& out) {
    QuerySketchConfig cfg;
    cfg.ref = sketch;
    cfg.out = out;
    cfg.threads = 4;
    cfg.sketchHit = 10;
    cfg.readCutoff = 2;

    SketchHash sketchHash;
    std::vector<std::string> sketchRef;
    std::vector<SketchHash> refSigCount;
    loadSketch(cfg, cfg.ref, sketchHash, sketchRef, refSigCount);
    assert(cfg.kmerLen == 31 && "loadSketch must recover k from the index");

    std::vector<std::string> samples = {FIX + "reads.fq.gz"};
    size_t totalKmers = 0;
    getCardinality(totalKmers, cfg.dbfSize, cfg.sbfSize, cfg.kmerLen, cfg.threads, samples);
    bool sized = resolveBloomSizes(totalKmers, cfg.dbfSize, cfg.sbfSize);
    assert(sized);

    std::vector<unsigned> sketchCount(sketchRef.size(), 0);
    std::vector<std::unordered_set<std::string>> refRead(sketchRef.size());
    querySampleBatch(cfg, samples, sketchHash, sketchCount, refSigCount, refRead);
    generateQueryResult(cfg, sketchCount, sketchRef, refSigCount, refRead, cfg.out);
}

}  // namespace

void testIndexIsDeterministic() {
    std::cerr << "START: Test e2e index build is deterministic... \t";
    buildIndex(WORK + "idx1", WORK + "sketch1.tsv");
    buildIndex(WORK + "idx2", WORK + "sketch2.tsv");
    std::string a = fileContents(WORK + "sketch1.tsv");
    std::string b = fileContents(WORK + "sketch2.tsv");
    assert(!a.empty());
    assert(a == b && "two builds of the same index differ");
    std::cerr << "PASSED: Test e2e index build is deterministic\n";
}

void testIndexShape() {
    std::cerr << "START: Test e2e index shape... \t";
    // Every indexed reference must receive signatures, including the variant,
    // whose candidate pool is only the k-mers overlapping its 12 edits.
    std::map<std::string, unsigned> perRef;
    std::ifstream in(WORK + "sketch1.tsv");
    std::string line;
    while (std::getline(in, line)) {
        std::istringstream ss(line);
        std::string sig, refName;
        unsigned refId;
        ss >> sig >> refId >> refName;
        assert(sig.size() == 31);
        perRef[refName]++;
    }
    assert(perRef.size() == 3);
    assert(perRef["refA"] == 100 && perRef["refB"] == 100);
    // 12 edits x up to 31 overlapping k-mers each = at most 372 candidates; with
    // sketchnum=100 the variant should be fully populated.
    assert(perRef["refA_var"] == 100);
    std::cerr << "PASSED: Test e2e index shape\n";
}

void testQueryAbundance() {
    std::cerr << "START: Test e2e query abundance... \t";
    runQuery(WORK + "sketch1.tsv", WORK + "result.tsv");
    auto rows = readResult(WORK + "result.tsv");
    auto truth = readTruth();

    // Exactly the three indexed references, and nothing else: refC is in the
    // reads but not the index and must not appear.
    assert(rows.size() == 3 && "unexpected number of reported references");
    assert(rows.count("refC") == 0 && "unindexed organism must not be reported");
    for (const auto& [ref, expected] : truth) {
        assert(rows.count(ref) && "an indexed, present reference was not reported");
    }

    // Abundance sums to 1 over reported rows.
    double sum = 0;
    for (const auto& [ref, r] : rows) sum += r.abundance;
    assert(std::abs(sum - 1.0) < 1e-6);

    // Abundance tracks the mixture. Signatures are placed evenly along each
    // genome and reads are uniform, so hits are proportional to depth. The
    // absolute tolerance is 2.5 percentage points. The intrinsic noise here is
    // about 1 pp, and almost all of it comes from refA_var: its 500 reads fall on
    // signatures concentrated at 12 edit sites, so its count is quantised, and
    // that noise reaches every share through the common denominator. 2.5 pp
    // sits clear of that while still failing on the class of error that matters
    // -- shared k-mers leaking between siblings moves shares by tens of points
    // (a mutation that stops recording repeats drove refA from 0.70 to 0.43).
    for (const auto& [ref, expected] : truth) {
        double got = rows[ref].abundance;
        if (std::abs(got - expected) > 0.025) {
            std::cerr << "\n  " << ref << ": expected " << expected << " got " << got << "\n";
            assert(false && "abundance outside tolerance");
        }
    }

    // The absorption contract, checked exactly and independently of the noisy
    // denominator. refC (unindexed, a relative of refB) contributes its reads to
    // refB: refB's signatures are unique against the index, and refC is not in
    // the index, so the k-mers they share stay legitimate refB signatures. refA
    // and refB both carry 100 evenly spaced signatures over 20 kb, so their hits
    // per source read must agree; if refC's 500 reads were NOT being absorbed,
    // refB's rate would come out 500/3000 = 17% low. Ratio tolerance 8% covers
    // signature-placement variation (hits/read ~ 100 * (readLen - k + 1) / 20 kb
    // differs slightly per genome) without reaching that 17% gap.
    const double rateA = rows["refA"].count / 7000.0;
    const double rateB = rows["refB"].count / (2500.0 + 500.0);   // refB + absorbed refC
    const double ratio = rateB / rateA;
    if (std::abs(ratio - 1.0) > 0.08) {
        std::cerr << "\n  hits/read refA=" << rateA << " refB(+refC)=" << rateB
                  << " ratio=" << ratio << "\n";
        assert(false && "refC reads not absorbed by refB as the contract requires");
    }

    // Evidence columns are internally consistent.
    for (const auto& [ref, r] : rows) {
        assert(r.resolution == "strain");
        assert(r.reads <= r.count && "a read contributes at least one hit");
        assert(static_cast<int>(r.reads) > 2 && "must exceed readCutoff to be reported");
        assert(r.sigsTotal == 100);
        assert(r.sigsHit >= 1 && r.sigsHit <= r.sigsTotal);
    }
    // At 70% of 10,500 reads over 20 kb, every one of refA's 100 signatures
    // should be covered; refB likewise at 25%.
    assert(rows["refA"].sigsHit == 100);
    assert(rows["refB"].sigsHit == 100);

    std::cerr << "PASSED: Test e2e query abundance\n";
}

int main() {
    mkdir(WORK.c_str(), 0777);

    testIndexIsDeterministic();
    testIndexShape();
    testQueryAbundance();

    std::cerr << "E2E: All tests PASSED!\n\n";
    return 0;
}
